const size_t SIZE = 4096 * 2;

// Allocate anonymous memory region
void *addr = mmap(NULL, SIZE, PROT_READ | PROT_WRITE,
                  MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

// Lock memory immediately (flags 0 is similar to mlock())
int status_full = mlock2(addr, SIZE, 0);

// Prepare MLOCK_ONFAULT flag
unsigned int flags = MLOCK_ONFAULT;

// Lock memory only upon page fault/access
int status_onfault = mlock2(addr, SIZE, flags);

munlock(addr, SIZE);
munmap(addr, SIZE);
